      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "Cada 4 turnos enemigos, todos los esbirros lobo ganan permanentemente +1 de Ataque.",
      "银灰狼女猎手": "Cazadora Lobo Plateada Gris",
      "千枝城的灰牙首领": "Líder Colmillo Gris de Ciudad de las Mil Ramas",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "La jefa lobo que eludió a los perseguidores de Ciudad Esmeralda y tomó las ruinas de Ciudad de las Mil Ramas. Cada turno invoca un rápido lobo gris a la batalla.",
