      "留守的农民夫妇": "La Pareja de Granjeros que se Quedó",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Tranquilo, joven. Esos osos no han matado a nadie aquí. Cuando llegaron a la granja, solo alejaron a los aldeanos hacia la capital real.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "Nos quedamos porque nunca sentimos hostilidad de ellos. Al principio ni siquiera sabían cómo sostener un arado; solo revolvían los campos en un desorden por fuerza bruta.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Más tarde enseñamos a los hombres oso a reparar los canales y sembrar trigo, y a las mujeres oso a cuidar las colmenas y traer la cosecha. Aprenden lentamente, pero nunca desperdician comida.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "Guardan el lugar más cálido del granero para sus cachorros, y traen el primer saco de trigo nuevo a nuestra puerta. Al menos en nuestros ojos, no son tan viles como dicen los rumores.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "Si debes continuar, vélo con tus propios ojos antes de juzgar. Lo que pasó aquí puede no ser un simple caso de monstruos apoderándose de un pueblo.",
