      "火灾救援、灾后重建与对重生者的身份登记": "Rescate de fuego, reconstrucción de desastres y registro de identidad para los renacidos",
      "黑锋骑士团": "Orden de Filo Negro",
      "让锋刃只指向准备好应战的人": "Que la hoja apunte solo a quienes están listos para pelear",
      "蒲公英花灵": "Hadas de Diente de León",
      "市集、印刷术与允许异族登台的演出许可": "Mercados, impresión y licencias de actuación que permitan a otras razas tomar el escenario",
      "血斧角斗场": "Arena del Hacha de Sangre",
      "裁判最好离远点，我的胜利通常会溅到前三排": "El árbitro debe retroceder, mis victorias usualmente salpican las primeras tres filas",
      "晶辉学院": "Academia de Radiancia de Cristal",
      "用晶体测量魔力，让法术可以被复现": "Midiendo la magia con cristales para que los hechizos puedan ser reproducidos",
      "鹿角兽人": "Pueblos de Bestias Cornudas",
      "护林法、共享牧道与边地自治议会": "Leyes de protección forestal, rutas de pastoreo compartidas y consejos de autogobierno fronterizo",
      "机巧侏儒": "Gnomos de Relojería",
      "专利制度、公开船坞与事故追责": "Sistemas de patentes, astilleros abiertos y responsabilidad por accidentes",
      "虚空观测站": "Observatorio del Vacío",
      "用长期观测区分天启、幻觉和噪声": "Observación a largo plazo para distinguir revelación de ilusión y ruido",
      "黄金狮鹫族": "Grifos Dorados",
      "空骑军籍、兽族居住权与救援航线": "Enlistamiento de jinetes del cielo, residencia de pueblos y rutas de vuelo de rescate",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "No me uní al reino para convertirme en humano, sino porque aquí puedo seguir siendo yo mismo y avanzar por mi propio mérito.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "El linaje solo decide dónde nacemos; las instituciones y las elecciones deciden si podemos estar lado a lado aquí.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Hoy no represento sumisión, sino un reino donde otras razas pueden competir abiertamente y ganar aplausos justos y legítimos.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Hermoso. Empujarme tan lejos prueba que la capital realmente acoge a un oponente digno de respeto.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "No probaré correctos esos prejuicios de que otras razas pertenecen ocultas en lo salvaje. Vamos, ¡ronda final!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "Ganaste. Que esta arena siga probando: humanos y otras razas pueden competir sin odiarse los unos a los otros.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Juega más rápido. El público no compró entradas para verte reflexionar sobre la vida.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "¿Eso es una línea de batalla? Mi cuerda de ropa es más difícil de romper.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Relájate, te dejaré algo de dignidad, al menos esperaré el llamado del árbitro antes de reírme.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Deja de mirar el marcador. No va a cambiar de lado solo porque lo mires fijamente.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "Ese último movimiento fue decente. Pero para hacerme callar, aún tienes un último tramo por recorrer.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "¡No saludes a la multitud todavía! Solo estoy guardando mi regreso para cuando sea más ruidoso.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "Ganaste hoy. La próxima vez te venceré primero, luego presentaré una queja sobre este piso que obviamente te favorece.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "No me importa, estoy grabando tus hábitos de juego. Los datos verdaderamente peligrosos a menudo vienen de personas seguras.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Cada intercambio estrecha la respuesta. Algunos turnos más y solo te quedará una opción.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "La arena es más honesta que el laboratorio: las teorías incorrectas pierden Salud en el acto.",
      "放心，若你击败我，我会如实把结论写进报告。": "Asegúrate, si me vences, escribiré la conclusión en mi informe fielmente.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "Los datos se desvían de la predicción. Bien, la investigación sin sorpresas es la más aburrida.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "Ahora la muestra está verificando al investigador... Admito que este resultado es muy convincente.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Conclusión confirmada: tu juicio en el momento vence a mi modelo. El siguiente borrador de mi trabajo lo dirá.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "No hay verdaderos enemigos en la arena, solo personas dispuestas a mostrar sus habilidades a la luz del sol.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "No abandones la línea para salvarte. El honor viene de tomar riesgos, no de evitarlos.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "La multitud recuerda el resultado; un guerrero debe recordar las elecciones hechas bajo presión.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "No contengas. La mejor forma de respetar a un oponente es traer la fuerza que verdaderamente quiere ganar.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "Un excelente avance frontal. El dolor pasa; perder tu juicio es la verdadera derrota.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Solo un último punto de Salud, perfecto para probar el último resto de voluntad.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "El combate está decidido. He memorizado tus tácticas y guardaré mis aplausos para quienes lo merecen.",
      "并": "y",
      "，它们可以立即攻击": ", y pueden atacar inmediatamente",
      "和": "y",
      "永久": "permanentemente",
      "本回合": "este turno",
      "发动独特的竞技场英雄技能。": "Utiliza una habilidad de héroe de arena única.",
      "斩击": "Tajo",
