      "💧 胶质再生：首领与随从恢复生命": "💧 Regeneración de Gel: el jefe y los esbirros restauran Salud",
      "碧露近卫": "Guardia de Rocío Azur",
      "生命": "Salud",
      "战场上没有狼类随从，技能未强化任何单位。": "No hay esbirros lobo en el campo de batalla; la habilidad no potenciaba ninguna unidad.",
      "🐺 狼王咆哮发动！": "🐺 ¡Se desató el Aullido del Rey Lobo!",
      "接管战场，准备主动反击": "Toma el control del campo de batalla y prepárate para contraatacar",
      "封锁全部前排": "Sella toda la primera fila",
      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "Los cuatro oficiales súcubo se niegan a retirarse y contraatacan a la vez con 20 de Ataque; el escuadrón será rechazado, pero el Capítulo 5 aún se cuenta como despejado.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "Los cuatro oficiales súcubo no atacan; solo mantienen la barrera, comprando dos turnos para que su camarada escape.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "Comienza contraataque de Mil Ramas: los cuatro oficiales súcubo golpean al escuadrón uno a uno con 20 de Ataque.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "El asalto de los cuatro oficiales rompe la línea, y la vanguardia de la Alianza Demoníaca cruza la grieta para tomar las ruinas; el escuadrón es expulsado de la Ciudad de las Mil Ramas.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "Los cuatro oficiales súcubo derrotaron al escuadrón, pero la Cazadora de Lobo Gris Plateada ya ha sido derrotada: la historia del Capítulo 5 está completa, y todo el botín y recompensas de despeje se otorgan como de costumbre.",
      "你的英雄倒下了。冒险结束。": "Tu héroe ha caído. La aventura ha terminado.",
