      "选择发光的敌方目标；若有突破路线，也可以点击敌方英雄。": "Elige un objetivo enemigo brillante; si un carril está abierto, también puedes hacer clic en el héroe enemigo.",
      "武器已举起：选择敌方随从；若有突破路线，也可以攻击敌方英雄。": "Arma levantada: elige un esbirro enemigo; si un carril está abierto, también puedes atacar al héroe enemigo.",
