      "追寻银灰狼女猎手": "Rastrea a la Cazadora de Lobo Gris Plateada",
      "追寻碧露大贤者": "Busca al Gran Sabio del Rocío Azur",
      "踏入金麦农场": "Entra en la Granja de Trigo Dorado",
      "会见丰穗战母": "Conoce a la Madre de Guerra de la Cosecha",
      "进军王庭": "Marcha hacia la Corte",
      "挑战翠影女王": "Desafía a la Reina Sombra Esmeralda",
      "击穿战线": "Rompe la Línea de Batalla",
      "直面狼王": "Enfrenta al Rey Lobo",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "El Capítulo 5 se encuentra en las ruinas antiguas al sur de la Ciudad Esmeralda. Los lobos grises y otras bestias expanden su territorio con rapidez y emboscadas; al final te enfrentas a la Cazadora de Lobo Gris Plateada.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "El Capítulo 4 tiene veinte nodos de jefe de limo. Tienen Salud gruesa, Ataque bajo y se regeneran constantemente; sigue la corriente brillante profundamente en el bosque para enfrentar al Gran Sabio Nephrie del Rocío Azur.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "El Capítulo 3 tiene veinte nodos de jefe oso y una granja. Sigue los senderos de la granja para investigar la aldea ocupada, y finalmente enfrenta a la Madre de Guerra de la Cosecha Breya.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "El Capítulo 2 tiene veinte nodos de jefe. Avanza a lo largo de las defensas del ejército trasgo y finalmente enfrenta a la Reina Sombra Esmeralda con 200 de Salud.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Despliega tu ejército en cuatro carriles de batalla con primeras y segundas filas, abre una brecha y cruza trece nodos del Bosque Brumoso. Cada victoria se convierte en fortaleza para la próxima expedición.",
      "重新开始本关": "Reinicia Este Capítulo",
      "当前没有伤员": "No hay unidades heridas",
      "单机卡牌闯关冒险": "Una aventura de cartas para un jugador",
      "关卡选择": "Seleccionar Capítulo",
      "英雄档案": "Perfil de Héroe",
      "卡组编辑": "Constructor de Mazo",
      "设置": "Configuración",
      "队伍营地": "Campamento del Equipo",
      "每项卡牌训练或救治服务均需30金币。阵亡的真实随从会进入伤员名单，救治后才能重新出战。": "Cada entrenamiento de carta o servicio de sanación cuesta 30 oro. Los esbirros reales que mueren van a la lista de heridos y deben ser sanados antes de poder pelear de nuevo.",
      "⚔️ 随从训练 · 30金币": "⚔️ Entrenamiento de Esbirro · 30 oro",
      "选择任意一张未满级随从牌，增加2点经验": "Elige cualquier carta de esbirro por debajo del nivel máximo para ganar 2 EXP",
      "✨ 法术训练 · 30金币": "✨ Entrenamiento de Hechizo · 30 oro",
      "选择任意一张未满级法术牌，增加2点经验": "Elige cualquier carta de hechizo por debajo del nivel máximo para ganar 2 EXP",
