      "战斗经验、法力和技能成长会跨冒险保存。": "El EXP de batalla, maná y crecimiento de habilidad se transfieren entre aventuras.",
      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Fue capitán de la Guardia Real de la capital. Cuando las bestias empezaron a despertar una tras otra, decidió que proteger una sola capital no bastaba: la dejó, reunió a su propio escuadrón y partió a sofocar los disturbios por todo el reino.",
