      "归乡之战幸存者的七堂课": "Siete Lecciones de Sobrevivientes de la Guerra del Regreso",
      "每关首次通关永久增加1点最大法力；没有碎片，也没有总上限。重复挑战不会重复获得法力。": "La primera victoria de cada prueba añade permanentemente 1 de Maná Máximo; sin fragmentos y sin límite general. Las victorias repetidas no otorgan maná nuevamente.",
