      "返回训练场": "Volver al Terreno de Entrenamiento",
      "试炼暂未通过": "Prueba Aún No Superada",
      "试炼不会消耗远征生命或地图进度。调整战术后可以立即重试。": "Las pruebas no consumen la Salud de la expedición ni el progreso del mapa. Ajusta tus tácticas e intenta nuevamente de inmediato.",
      "请先击败森林狼王解锁第二关。": "Derrota al Rey Lobo del Bosque primero para desbloquear el Capítulo 2.",
