      "已击败的节点、路线解锁和本轮奖励都会保留。之后点击“继续游戏”即可从当前进度继续。": "Los nodos derrotados, rutas desbloqueadas y recompensas de esta carrera se mantienen todos. Haz clic en \"Continuar\" más tarde para reanudar desde tu progreso actual.",
