      "只留下最终首领？": "¿Dejar solo el jefe final?",
      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "Configura el Capítulo 5 para que los primeros 19 jefes sean derrotados, dejando solo a la Cazadora Loba Gris Plateada. Tu héroe, oro, colección, mazo y otros almacenamientos de capítulos no cambiarán.",
