      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0} ha sido llevado por el quinto oficial. Los cuatro oficiales 10/200 sellan la primera fila y se retirarán en {1} turnos.",
      "你的回合 · 第{0}回合": "Tu Turno · Turno {0}",
      "{0}的回合": "Turno de {0}",
      "法力每回合恢复至 {0}/{1}，不会自动增长。": "El maná se restaura a {0}/{1} cada turno y no crece automáticamente.",
      "{0} {1} · {2}费": "{0} {1} · {2} maná",
