      "{0}第{1}关 · 已完成{2}节点": "{0} Capítulo {1} · {2} nodos completados",
      "救治全部{0}名伤员": "Sana todos los {0} heridos",
      "· 英雄生命 {0}/{1}，同时恢复满生命": "· Salud del Héroe {0}/{1}, también completamente restaurada",
      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "Se restaura a {0}/{1} cada turno. El límite permanente no tiene límite y solo se puede aumentar mediante primeras victorias de Pruebas del Comandante.",
      "{0} 场胜利 · {1} 次通关 · 收藏 {2} 张": "{0} victorias · {1} victorias · {2} cartas coleccionadas",
