      "森灵德鲁伊": "Druida del Bosque",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "La tiradora más joven de la frontera boscosa; sus flechas atraviesan capas de ramas para hallar a los enemigos ocultos tras las líneas.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "Una bruja que dejó la torre de magos para estudiar la Grieta en solitario; divide el maná en incontables proyectiles difíciles de esquivar.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "Una santa enviada al frente por el Templo del Sol; cree que cada soldado merece volver a levantarse.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "Un caudillo de las tribus del norte que enciende la furia de sus guerreros con su propia sangre.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Líder de los guardabosques de Bosqueluna; siempre hace que el enemigo vea arqueros en las sombras donde no debería haberlos.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "Veterano de la Orden del Alba de la capital; su muro de escudos jamás ha retrocedido un paso.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "Una druida nacida del corazón del bosque antiguo; cada brote que planta se convierte en un árbol ancestral que protege el bosque.",
