      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "Ignorando la protección de la primera fila, inflige {0} de daño a cualquier esbirro enemigo; si muere, roba 1 carta.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "Dispara {0} proyectiles arcanos; cada uno inflige 1 de daño a un esbirro enemigo o al héroe enemigo al azar.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "Restaura por completo la salud de todos los esbirros aliados y restaura {0} de salud a tu héroe.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "Tu héroe pierde 2 de salud; un esbirro aliado gana +{0} de ataque este turno y puede volver a atacar de inmediato.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "Invoca en la fila trasera un Arquero Sombrahoja a distancia de {0}/{1}; puede atacar esbirros de inmediato.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "Todos los esbirros aliados de la primera fila ganan +{0} de salud permanente; si tu primera fila está vacía, invoca un Guardián Égida de 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "Invoca un Brote Ancestral de {0}/{1}; al inicio de cada uno de tus turnos gana +1/+1 permanente.",
